import { isSecretRef } from "../types.js";
/**
 * The omitted-`webhookSecret` fallback: a {@link SecretRef} naming `envName`,
 * present only while that env var is non-empty at channel construction.
 * Named rather than read so the fallback keeps the same route policy (and
 * the same control-plane catch declaration) as an authored
 * `{ secretName: envName }`.
 */
export function envSecretRef(envName) {
    const value = process.env[envName]?.trim();
    return value === undefined || value === "" ? undefined : { secretName: envName };
}
/**
 * The secret's value for the handler's own check. A named secret resolves
 * from the environment: locally the shell's, hosted the bound deployment
 * secrets. Empty and whitespace-only values count as unset.
 */
export function resolveWebhookSecretValue(value) {
    if (value === undefined) {
        return undefined;
    }
    const resolved = typeof value === "function"
        ? value()
        : isSecretRef(value)
            ? process.env[value.secretName]
            : value;
    const trimmed = resolved?.trim();
    return trimmed === undefined || trimmed === "" ? undefined : trimmed;
}
/**
 * What the handler does with a webhook secret.
 *
 * `{ secret }` when a value resolved. The handler verifies the delivery.
 * `"missing"` when a literal or a getter resolved empty. The handler
 * rejects the request.
 * `"none"` when the secret is omitted or named. Route auth owns that
 * case, including a default secret name that is unset.
 */
export function resolveWebhookSecretCheck(configured, resolved) {
    if (resolved !== undefined && resolved !== "") {
        return { secret: resolved };
    }
    if (configured === undefined || isSecretRef(configured)) {
        return "none";
    }
    return "missing";
}
/**
 * Why an SCM channel cannot deploy onto architecture v2 as authored, or
 * `undefined` when it can. v2 terminates the provider's webhook check on
 * the control plane, which can only do that for a secret it can name: a
 * literal or getter value never reaches the manifest, so the check would
 * run inside the guest only — after compute was spent and after the SCM
 * already got its 202. Omitting the field (the env fallback) is allowed.
 */
export function namedWebhookSecretArchitectureError(args) {
    if (args.webhookSecret === undefined || isSecretRef(args.webhookSecret)) {
        return undefined;
    }
    const authored = typeof args.webhookSecret === "function" ? "a function" : "a literal value";
    return (`${args.option} is ${authored}; architecture "v2" requires a named secret: ` +
        `{ secretName: "${args.envName}" }. The control plane verifies ${args.verifies} with ` +
        `the deployment secret of that name before any compute starts; a literal or function value is ` +
        `only checkable inside the guest. Set the value with \`secrets set <slug> ${args.envName}\`.`);
}
